package blockbranch.client.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.world.level.block.Blocks;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.client.gui.screens.TitleScreen;import blockbranch.realistic.*;
/** Connected-player native brush use, actual submerged structures, then persistent reopen. */
public final class DeepColdRuinView {
 private static final boolean REOPEN=Boolean.getBoolean("blockbranch.deepColdRuinViewReopen");
 private static boolean opened,saving,prepared,useStarted;private static volatile boolean posed,brushing;private static volatile int view;private static int settled,brushTicks,entityWait;private static long began;
 private static volatile BlockPos brushTarget;private static volatile List<BlockPos> anchors=List.of();private static final List<Object> records=new ArrayList<>();private static List<String> ids;private static net.minecraft.world.level.levelgen.structure.StructureStart start;private static DeepColdOceanRuins.Plan target;
 private static Path dir(){return Path.of(System.getProperty("blockbranch.deepColdRuinViewDir"));}
 private static void write(String name,Object value)throws Exception{Files.writeString(dir().resolve(name),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(value));}
 private static void require(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void register(){
  ServerTickEvents.END_SERVER_TICK.register(server->{if(server.isDedicatedServer()||server.getPlayerList().getPlayers().isEmpty())return;try{
   var player=server.getPlayerList().getPlayers().getFirst();var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var random=level.getChunkSource().randomState();
   if(!prepared){var report=com.google.gson.JsonParser.parseString(Files.readString(Path.of(System.getProperty("blockbranch.deepColdRuinWitness")))).getAsJsonObject();ids=report.getAsJsonArray("residentIds").asList().stream().map(v->v.getAsString()).toList();var p=report.getAsJsonObject("witness");target=g.deepColdRuins(random).forStart(p.get("x").getAsInt()>>4,p.get("z").getAsInt()>>4).orElseThrow();var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(net.minecraft.world.level.levelgen.structure.BuiltinStructures.OCEAN_RUIN_COLD);var chunk=level.getChunk(target.x()>>4,target.z()>>4);start=level.structureManager().getStartForStructure(holder.value(),chunk);require(start!=null&&start.isValid(),"Actual saved native ruin group");var box=start.getBoundingBox();for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)level.getChunk(x,z);var commands=server.getCommands();var source=server.createCommandSourceStack();commands.performPrefixedCommand(source,"gamemode creative "+player.getName().getString());commands.performPrefixedCommand(source,"time set 6000");commands.performPrefixedCommand(source,"weather clear");commands.performPrefixedCommand(source,"effect clear "+player.getName().getString()+" minecraft:night_vision");commands.performPrefixedCommand(source,"effect give "+player.getName().getString()+" minecraft:water_breathing 100000 0 true");player.getAbilities().flying=true;player.onUpdateAbilities();prepared=true;}
   if(REOPEN){var record=com.google.gson.JsonParser.parseString(Files.readString(dir().resolve("brush.json"))).getAsJsonObject();var a=record.getAsJsonArray("position");var at=new BlockPos(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt());require(level.getBlockState(at).is(Blocks.GRAVEL),"Actually brushed block stays excavated after native client reopen");if(ids.stream().anyMatch(id->level.getEntity(UUID.fromString(id))==null)){require(++entityWait<200,"Saved resident entity admission on client reopen");return;}require(ids.stream().allMatch(id->level.getEntity(UUID.fromString(id)).isAlive()),"Original persistent drowned UUIDs on client reopen");write("brush-reopen.json",Map.of("excavatedPosition",at.toShortString(),"residentIds",ids,"passed",true));Files.writeString(dir().resolve("result.txt"),"PASS actual brushed gravel and original drowned UUIDs survive native client reopen");return;}
   if(brushing){if(level.getBlockState(brushTarget).is(Blocks.GRAVEL)){var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(brushTarget).inflate(2)).stream().map(e->Map.of("item",net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(e.getItem().getItem()).toString(),"count",e.getItem().getCount())).toList();var receipts=new ArrayList<Object>();receipts.addAll(drops);for(int slot=0;slot<player.getInventory().getContainerSize();slot++){var item=player.getInventory().getItem(slot);if(!item.isEmpty()&&!item.is(net.minecraft.world.item.Items.BRUSH))receipts.add(Map.of("item",net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item.getItem()).toString(),"count",item.getCount(),"location","player inventory"));}require(!receipts.isEmpty(),"Actual native brush produced loot");write("brush.json",Map.of("position",new int[]{brushTarget.getX(),brushTarget.getY(),brushTarget.getZ()},"lootReceipts",receipts,"residentIds",ids,"nativeItemUse",true,"ticks",brushTicks));brushing=false;view=4;posed=false;}else require(++brushTicks<400,"Actual brush use timeout");return;}
   if(posed)return;var box=start.getBoundingBox();var first=(ColdRuinAccess)start.getPieces().getFirst();BlockPos camera,aim;double pitchOverride=Double.NaN;
   if(view<=1){if(view==1)server.getCommands().performPrefixedCommand(server.createCommandSourceStack(),"effect give "+player.getName().getString()+" minecraft:night_vision 100000 0 true");camera=new BlockPos(box.minX()+4,box.maxY()+8,box.minZ()+4);aim=new BlockPos((box.minX()+box.maxX())/2,box.minY()+2,(box.minZ()+box.maxZ())/2);}
   else if(view==2){int mid=first.blockbranch$coldSize().getX()/2;camera=first.blockbranch$coldLocal(mid,4,-12);aim=first.blockbranch$coldLocal(mid,1,5);}
   else{if(brushTarget==null){outer:for(int y=box.maxY();y>=box.minY();y--)for(int z=box.minZ();z<=box.maxZ();z++)for(int x=box.minX();x<=box.maxX();x++){var at=new BlockPos(x,y,z);if(level.getBlockState(at).is(Blocks.SUSPICIOUS_GRAVEL)&&level.getBlockState(at.above()).is(Blocks.WATER)&&level.getBlockState(at.above(2)).is(Blocks.WATER)&&level.getBlockState(at.above(3)).is(Blocks.WATER)&&level.getBlockState(at.above(4)).is(Blocks.WATER)&&level.getBlockState(at.above(5)).is(Blocks.WATER)){brushTarget=at;break outer;}}require(brushTarget!=null,"Exposed native archaeological block");}camera=brushTarget.above(3);aim=brushTarget;pitchOverride=90;player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.BRUSH));player.containerMenu.broadcastChanges();if(view==3)for(int slot=0;slot<player.getInventory().getContainerSize();slot++){var item=player.getInventory().getItem(slot);require(item.isEmpty()||item.is(net.minecraft.world.item.Items.BRUSH),"Brush proof begins with no loot in inventory");}}
   double cx=camera.getX()+.5,cy=camera.getY(),cz=camera.getZ()+.5,dx=aim.getX()+.5-cx,dz=aim.getZ()+.5-cz,dy=aim.getY()+.5-(cy+player.getEyeHeight());double yaw=Math.toDegrees(Math.atan2(-dx,dz)),pitch=Double.isNaN(pitchOverride)?Math.toDegrees(Math.atan2(-dy,Math.hypot(dx,dz))):pitchOverride;server.getCommands().performPrefixedCommand(server.createCommandSourceStack(),"tp "+player.getName().getString()+" "+cx+" "+cy+" "+cz+" "+yaw+" "+pitch);
   var points=new ArrayList<BlockPos>();for(var piece:start.getPieces()){var access=(ColdRuinAccess)piece;if(access.blockbranch$coldStage()==0)points.add(access.blockbranch$coldLocal(access.blockbranch$coldSize().getX()/2,0,access.blockbranch$coldSize().getZ()/2));}anchors=List.copyOf(points);records.add(Map.of("view",view,"camera",camera.toShortString(),"witness",target,"nativePieces",start.getPieces().size()));blockbranch.Blockbranch.LOGGER.info("DEEP_COLD_RUIN_VIEW_POSED {}",view);posed=true;
  }catch(Throwable e){blockbranch.Blockbranch.LOGGER.error("DEEP_COLD_RUIN_VIEW_FAIL",e);try{Files.writeString(dir().resolve("result.txt"),"FAIL "+e);}catch(Exception ignored){}}});
  ClientTickEvents.END_CLIENT_TICK.register(client->{try{
   if(opened&&System.nanoTime()-began>600_000_000_000L){Files.writeString(dir().resolve("result.txt"),"FAIL native ruin view timeout");client.stop();return;}
   if(!opened&&client.gui.screen() instanceof TitleScreen){opened=true;began=System.nanoTime();client.createWorldOpenFlows().openWorld("DeepColdRuinReview",()->client.gui.setScreen(new TitleScreen()));return;}
   if(Files.exists(dir().resolve("result.txt"))){client.options.keyUse.setDown(false);client.stop();return;}if(client.level==null||client.player==null||REOPEN)return;
   if(brushing){if(client.hitResult instanceof net.minecraft.world.phys.BlockHitResult hit&&hit.getBlockPos().equals(brushTarget)&&client.player.getMainHandItem().is(net.minecraft.world.item.Items.BRUSH)){client.options.keyUse.setDown(true);if(!useStarted){client.gameMode.useItemOn(client.player,net.minecraft.world.InteractionHand.MAIN_HAND,hit);useStarted=true;}}return;}else client.options.keyUse.setDown(false);
   if(!posed||saving)return;client.options.fov().set(view<=1?85:view==2?65:50);if(!client.gui.hud.isHidden())client.gui.hud.toggle();client.gui.toastManager().clear();var area=client.levelRenderer.viewArea();if(area==null)return;int ready=0;for(var at:anchors){boolean visible=false;for(int dy:new int[]{-16,0,16}){var section=area.getRenderSectionAt(at.offset(0,dy,0));visible|=section!=null&&section.getSectionMesh().hasRenderableLayers();}if(visible)ready++;}if(ready<Math.max(1,(int)Math.ceil(anchors.size()*.8))){settled=0;return;}if(++settled<(view==0?180:80))return;saving=true;
   String file=new String[]{"deep-cold-ruin-natural.png","deep-cold-ruin-overview-nv.png","deep-cold-ruin-wharf-nv.png","deep-cold-ruin-archaeology-nv.png","deep-cold-ruin-excavated-nv.png"}[view];net.minecraft.client.Screenshot.grab(client.gameDirectory,file,client.gameRenderer.mainRenderTarget(),1,message->client.execute(()->{try{if(view==3){brushing=true;saving=false;settled=0;}else if(view<4){view++;posed=false;saving=false;settled=0;}else{write("views.json",records);Files.writeString(dir().resolve("result.txt"),"PASS native cold ruin views and actual connected-player brush loot");client.stop();}}catch(Exception e){throw new RuntimeException(e);}}));
  }catch(Throwable e){blockbranch.Blockbranch.LOGGER.error("DEEP_COLD_RUIN_VIEW_CLIENT_FAIL",e);try{Files.writeString(dir().resolve("result.txt"),"FAIL "+e);}catch(Exception ignored){}client.stop();}});
 }
}
